#!/usr/bin/env python3
"""Execute PilotDB approximate queries from a SQL file generated by Java.

The SQL file (produced by Experiments -c generatePilotDBSqlFile) has the format:
    Line 1: -- measures: 5,6,12,17        (metadata comment)
    Line 2: CREATE TABLE data_table AS ... (table creation)
    Lines 3+: SELECT sum(...), avg(...) ... (one query per line)

Usage:
    python run_pilotdb_queries.py --sql-file pilotdb_mcols4.sql \
        --error 0.05 --out results.csv
"""

import argparse
import csv
import os
import sys
import time

import duckdb
import pilotdb


# ---------------------------------------------------------------------------
# SQL file parsing
# ---------------------------------------------------------------------------

def load_sql_file(sql_file):
    """Parse a PilotDB SQL file into (measure_cols, create_sql, select_queries).

    Returns:
        measure_cols: list of int column indices (from metadata comment)
        create_sql: the CREATE TABLE statement
        select_queries: list of SELECT statements
    """
    measure_cols = []
    create_sql = None
    select_queries = []

    with open(sql_file, 'r') as f:
        for line in f:
            line = line.strip()
            if not line:
                continue
            if line.startswith('-- measures:'):
                # Parse metadata: "-- measures: 5,6,12,17"
                parts = line.split(':', 1)[1].strip()
                measure_cols = [int(x) for x in parts.split(',')]
            elif create_sql is None and line.upper().startswith('CREATE'):
                create_sql = line
            else:
                select_queries.append(line)

    if create_sql is None:
        print("ERROR: No CREATE TABLE statement found in SQL file", file=sys.stderr)
        sys.exit(1)
    if not select_queries:
        print("ERROR: No SELECT queries found in SQL file", file=sys.stderr)
        sys.exit(1)

    return measure_cols, create_sql, select_queries


# ---------------------------------------------------------------------------
# Result formatting
# ---------------------------------------------------------------------------

def format_stats(result, measure_cols):
    """Convert PilotDB result into per-measure Stats strings.

    Returns stats_str.
    Layout: 2 values per measure column (sum, avg) in the order they appear in the SQL.
    """
    if result is None:
        return '{}'
    if hasattr(result, 'iloc'):
        result = tuple(result.iloc[0])
    if hasattr(result, 'empty') and result.empty:
        return '{}'

    stats_parts = []
    for j, col_idx in enumerate(measure_cols):
        offset = j * 2
        sum_val, avg_val = result[offset], result[offset + 1]
        stats_parts.append(f"{col_idx}=Stats{{sum={sum_val}, avg={avg_val}}}")

    return "{" + ", ".join(stats_parts) + "}"


# ---------------------------------------------------------------------------
# Query execution
# ---------------------------------------------------------------------------

CSV_FIELDS = ['csv', 'i', 'Time (sec)', 'Query', 'errorBound', 'Query Result', 'Init Timing']


def run(sql_file, output_file, error_bound, failure_prob=0.05, explain=False):
    measure_cols, create_sql, select_queries = load_sql_file(sql_file)

    # Extract csv path from CREATE TABLE for the output CSV column
    # (between read_csv_auto(' and ',)
    csv_path = ''
    if "read_csv_auto('" in create_sql:
        start = create_sql.index("read_csv_auto('") + len("read_csv_auto('")
        end = create_sql.index("'", start)
        csv_path = create_sql[start:end]

    # --- Setup database (timed) ---
    init_start = time.time()
    db_config = {"dbms": "duckdb", "path": ":memory:"}
    pilot_con = pilotdb.connect("duckdb", db_config)
    con = pilot_con["conn"]

    memory_limit = os.environ.get('DUCKDB_MEMORY_LIMIT')
    if memory_limit:
        con.execute(f"SET memory_limit = '{memory_limit}'")
    temp_dir = os.environ.get('DUCKDB_TEMP_DIR')
    if temp_dir:
        con.execute(f"SET temp_directory = '{temp_dir}'")

    if explain:
        print(f"  CREATE: {create_sql}")
    con.execute(create_sql)
    init_elapsed = time.time() - init_start
    print(f"Table creation: {init_elapsed:.2f}s")

    # --- Execute queries ---
    with open(output_file, 'w', newline='') as csvfile:
        writer = csv.DictWriter(csvfile, fieldnames=CSV_FIELDS)
        writer.writeheader()

        for i, sql in enumerate(select_queries):
            print(f"[Query {i}]")
            if explain:
                print(f"  SQL: {sql}")

            try:
                start = time.time()
                result = pilotdb.run(pilot_con, query=sql,
                                     error=error_bound, probability=failure_prob)
                elapsed = time.time() - start

                result_str = format_stats(result, measure_cols)
                if i == 0:
                    elapsed += init_elapsed
                writer.writerow({
                    'csv': csv_path, 'i': i, 'Time (sec)': elapsed,
                    'Query': sql, 'errorBound': error_bound,
                    'Query Result': result_str,
                    'Init Timing': '{tableCreation=%.3f, total=%.3f}' % (init_elapsed, init_elapsed) if i == 0 else '',
                })
            except Exception as e:
                print(f"ERROR in query {i}: {e}", file=sys.stderr)
                writer.writerow({
                    'csv': csv_path, 'i': i, 'Time (sec)': '',
                    'Query': sql, 'errorBound': error_bound,
                    'Query Result': '', 'Init Timing': '',
                })

    pilotdb.close(pilot_con)
    print(f"Results written to {output_file}")


# ---------------------------------------------------------------------------
# CLI
# ---------------------------------------------------------------------------

def main():
    parser = argparse.ArgumentParser(
        description="Execute PilotDB approximate queries from a Java-generated SQL file.")
    parser.add_argument('--sql-file', required=True,
                        help='SQL file generated by Experiments -c generatePilotDBSqlFile')
    parser.add_argument('--out', required=True, help='Output CSV file')
    parser.add_argument('--error', type=float, required=True,
                        help='Error bound for PilotDB (e.g. 0.05)')
    parser.add_argument('--probability', type=float, default=0.05,
                        help='Failure probability for PilotDB (default 0.05)')
    parser.add_argument('--explain', action='store_true',
                        help='Print generated SQL for each query')
    args = parser.parse_args()

    run(args.sql_file, args.out, error_bound=args.error,
        failure_prob=args.probability, explain=args.explain)


if __name__ == '__main__':
    main()
